    .withCoercionConfigDefaults(coercionConfig -> {
        coercionConfig.setCoercion(CoercionInputShape.String, CoercionAction.Fail);
    })
    .build();
TypeFactory typeFactory = new TypeFactory();

JavaType containerType;

